export const MOTHER_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: MOTHER_EASY_FOUNDATION,
    growth: MOTHER_EASY_GROWTH,
    mastery: MOTHER_EASY_MASTERY
  },
  medium: {
    foundation: MOTHER_MEDIUM_FOUNDATION,
    growth: MOTHER_MEDIUM_GROWTH,
    mastery: MOTHER_MEDIUM_MASTERY
  },
  hard: {
    foundation: MOTHER_HARD_FOUNDATION,
    growth: MOTHER_HARD_GROWTH,
    mastery: MOTHER_HARD_MASTERY
  },
};

export function getMotherStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = MOTHER_QUESTION_REGISTRY[diffKey] || MOTHER_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getMotherLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getMotherStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
